//! 🧪️ AP214 mixed geometry and Unicode annotations survive the independent Part21 reader.
use super::*;
#[test]
fn mixed_draughting_entities_match_the_portable_fixture_and_independent_parser(){let fixture:serde_json::Value=serde_json::from_str(include_str!("../🧪️fixtures/🔣️.json")).unwrap();let(mut writer,mut instances)=DraughtingWriter::new(1).unwrap();for item in fixture["primitives"].as_array().unwrap(){let point=|value:&serde_json::Value|[value[0].as_f64().unwrap(),value[1].as_f64().unwrap(),value[2].as_f64().unwrap()];let color=|value:&serde_json::Value|value.as_array().map(|_|point(value));let name=item["name"].as_str().unwrap();writer.set_curve_width(item["strokeWidth"].as_f64().unwrap_or(0.5*25.4/72.0)).unwrap();let part=match item["kind"].as_str().unwrap(){"path"=>writer.path(name,&item["points"].as_array().unwrap().iter().map(point).collect::<Vec<_>>(),color(&item["stroke"]),color(&item["fill"])).unwrap(),"circle"=>writer.circle(name,point(&item["center"]),item["radius"].as_f64().unwrap(),color(&item["stroke"])).unwrap(),_=>writer.text(name,item["text"].as_str().unwrap(),point(&item["position"]),item["rotation"].as_f64().unwrap(),item["width"].as_f64().unwrap(),item["height"].as_f64().unwrap(),item["fontSize"].as_f64().unwrap(),color(&item["color"])).unwrap()};instances.extend(part);}let mut header=Part21Header::default();header.file_schema=vec![Part21Value::List(vec![Part21Value::Str("AUTOMOTIVE_DESIGN".into())])];let doc=Part21Document{header,instances};let output=semio_s_artifact_stdio_contract::part21::write_part21(&doc);let rewritten=semio_s_artifact_stdio_step_test_oracle::standards::v_ap214::subsets::base::oracle_round_trip(output.as_bytes()).unwrap();let actual=semio_s_artifact_stdio_contract::part21::parse_part21(std::str::from_utf8(&rewritten).unwrap()).unwrap();assert_eq!(semio_s_artifact_stdio_step_test_oracle::standards::v_ap214::subsets::base::project_step_ap214_any(output.as_bytes()).unwrap(),semio_s_artifact_stdio_step_test_oracle::standards::v_ap214::subsets::base::project_step_ap214_any(&rewritten).unwrap());assert_eq!(actual.by_type("POLYLINE").count(),3);for curve in actual.by_type("POLYLINE"){assert!(curve.entity("POLYLINE").unwrap()[1].as_list().unwrap().len()>2);}assert_eq!(actual.by_type("CIRCLE").count(),1);assert_eq!(actual.by_type("ANNOTATION_FILL_AREA").count(),1);assert_eq!(actual.by_type("ANNOTATION_TEXT_OCCURRENCE").count(),1);assert_eq!(actual.by_type("TEXT_LITERAL_WITH_EXTENT").next().unwrap().entity("TEXT_LITERAL_WITH_EXTENT").unwrap()[1].as_str(),Some("Grüße & Layout"));let read=read_draughting(&actual).unwrap();assert!(read.issues.is_empty());assert_eq!(read.texts.len(),1);assert_eq!(read.paints.len(),4);let annotation=&read.texts[0];assert_eq!(annotation.literal,"Grüße & Layout");assert_eq!(annotation.color,Some([0.1,0.2,0.3]));assert!((annotation.font_size-4.0*read.unit_to_points).abs()<1e-9);assert!((annotation.x_axis[0]-0.2_f64.cos()).abs()<1e-12);let rectangle=actual.by_type("POLYLINE").find(|item|item.entity("POLYLINE").unwrap()[0].as_str()==Some("rectangle")).unwrap();let paint=read.paints.iter().find(|paint|paint.source_id==rectangle.id).unwrap();assert_eq!(paint.fill,Some([0.7,0.6,0.5]));assert_eq!(paint.stroke,Some([0.2,0.3,0.4]));assert!((paint.stroke_width.unwrap()-0.5).abs()<1e-12);let mut invalid=actual.clone();let color=invalid.instances.iter_mut().find(|instance|instance.is_type("COLOUR_RGB")).unwrap();let refusal=&fixture["refusals"][0];color.entities[0].1[refusal["argument"].as_u64().unwrap()as usize]=Part21Value::Real(refusal["value"].as_f64().unwrap().into());assert!(read_draughting(&invalid).unwrap().issues.iter().any(|issue|issue.contains(refusal["issue"].as_str().unwrap())));}
